import base64,csv,email.parser,hashlib,io,json,re,resource,signal,stat,sys,time
from pathlib import Path,PurePosixPath
resource.setrlimit(resource.RLIMIT_AS,(1073741824,1073741824));signal.alarm(120);tick=time.monotonic()
site=Path(settings['site']);target=Path(settings['target']);profiles={}
def norm(n):return re.sub('[-_.]+','-',n).lower()
def read(p):
 assert p.resolve()==p and stat.S_ISREG(p.lstat().st_mode) and p.stat().st_size<=16777216
 return p.read_bytes()
def digest(row):
 assert row[1].startswith('sha256=') and row[2].isascii() and row[2].isdigit()
 value=base64.urlsafe_b64decode(row[1][7:]+'='*((-len(row[1][7:]))%4)).hex();assert len(value)==64
 return value,int(row[2])
assert {str(p) for p in site.glob('*.dist-info/RECORD')}==set(settings['records'])
for filename,sha in sorted(settings['records'].items()):
 p=Path(filename);raw=read(p);assert hashlib.sha256(raw).hexdigest()==sha
 rows=list(csv.reader(io.StringIO(raw.decode()),strict=True));assert all(len(row)==3 for row in rows)
 matches=[row for row in rows if row[0]==p.parent.name+'/METADATA'];assert len(matches)==1
 msha,msize=digest(matches[0]);metadata=read(p.parent/'METADATA');assert len(metadata)==msize and hashlib.sha256(metadata).hexdigest()==msha
 parsed=email.parser.BytesParser().parsebytes(metadata);assert len(parsed.get_all('Name',[]))==len(parsed.get_all('Version',[]))==1
 name=norm(parsed['Name']);assert name not in profiles
 source_count=source_bytes=0
 for row in rows:
  rel=PurePosixPath(row[0])
  if rel.suffix!='.py' or rel.is_absolute() or '..' in rel.parts:continue
  _,size=digest(row);source_count+=1;source_bytes+=size
 deps=[]
 for value in parsed.get_all('Requires-Dist',[]):
  match=re.match(r'^([A-Za-z0-9][A-Za-z0-9_.-]*)',value);assert match,value
  deps.append({'name':norm(match.group(1)),'raw':value,'extra_marker':'extra' in value.split(';',1)[-1] if ';' in value else False})
 profiles[name]={'name':parsed['Name'],'version':parsed['Version'],'record':filename,'record_sha256':sha,'metadata_sha256':msha,'source_count':source_count,'source_bytes':source_bytes,'requires_dist':deps,'record_present_in_target':(target/p.relative_to(site)).is_file()}
seen=set();missing=set();todo=list(settings['selected_distributions'])
while todo:
 name=todo.pop()
 if name in seen:continue
 seen.add(name)
 if name not in profiles:missing.add(name);continue
 todo.extend(row['name'] for row in profiles[name]['requires_dist'] if not row['extra_marker'])
result={'schema':'original-record-backed-transitive-source-catalog-v1','profiles':profiles,'original_record_count':len(profiles),'candidate_distribution_names':sorted(seen),'missing_distributions':sorted(missing),'candidate_target_metadata_missing':sorted(n for n in seen if n in profiles and not profiles[n]['record_present_in_target']),'classification':'conservative dependency candidates; non-extra markers retained without host evaluation; not executable permission or exact import closure','elapsed_seconds':time.monotonic()-tick,'peak_rss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,'native_imports':False,'python_source_bytes_read':False,'target_modified':False,'native_qualified':False}
encoded=json.dumps(result,sort_keys=True);assert len(encoded.encode())<=16777216
assert not any(n.split('.')[0] in {'torch','numpy','PIL','transformers','safetensors','torchvision'} for n in sys.modules)
